// Handles.

/// A module being built, with everything made in it.
pub struct FirModule {
    mb: ModuleBuilder,
    inits: Vec<Init>,
    error: CString,
}

/// Builds one function of a module.
pub struct FirBuilder {
    module: *mut FirModule,
}

/// Why a call failed.
struct Fail {
    status: FirStatus,
    msg: String,
}

impl From<BuildError> for Fail {
    fn from(e: BuildError) -> Fail {
        Fail {
            status: FIR_ERR_INVALID,
            msg: e.message().to_owned(),
        }
    }
}

fn fail<T>(status: FirStatus, msg: impl Into<String>) -> Result<T, Fail> {
    Err(Fail {
        status,
        msg: msg.into(),
    })
}

fn c_string(s: String) -> CString {
    CString::new(s).unwrap_or_else(|e| {
        let mut bytes = e.into_vec();
        bytes.retain(|&b| b != 0);
        CString::new(bytes).expect("no NUL left")
    })
}

fn panic_message(p: &(dyn std::any::Any + Send)) -> String {
    let what = p
        .downcast_ref::<&str>()
        .map(|s| s.to_string())
        .or_else(|| p.downcast_ref::<String>().cloned())
        .unwrap_or_default();
    format!("internal error: {what}")
}

/// Run `f` on a module, catching panics. On failure, the module keeps the message and the call
/// returns `invalid`, or the failure's status when `status` is set.
unsafe fn with_module<T>(
    m: *mut FirModule,
    invalid: T,
    status: impl FnOnce(FirStatus) -> Option<T>,
    f: impl FnOnce(&mut FirModule) -> Result<T, Fail>,
) -> T {
    let Some(m) = (unsafe { m.as_mut() }) else {
        return status(FIR_ERR_INVALID).unwrap_or(invalid);
    };
    let out = catch_unwind(AssertUnwindSafe(|| f(&mut *m)));
    let e = match out {
        Ok(Ok(v)) => return v,
        Ok(Err(e)) => e,
        Err(p) => Fail {
            status: FIR_ERR_INTERNAL,
            msg: panic_message(&*p),
        },
    };
    m.error = c_string(e.msg);
    status(e.status).unwrap_or(invalid)
}

/// [`with_module`] for a call returning an id or a pointer (`invalid` on failure).
unsafe fn module_id<T>(
    m: *mut FirModule,
    invalid: T,
    f: impl FnOnce(&mut FirModule) -> Result<T, Fail>,
) -> T {
    unsafe { with_module(m, invalid, |_| None, f) }
}

/// [`with_module`] for a call returning a status.
unsafe fn module_status(
    m: *mut FirModule,
    f: impl FnOnce(&mut FirModule) -> Result<(), Fail>,
) -> FirStatus {
    unsafe { with_module(m, FIR_OK, Some, |m| f(m).map(|()| FIR_OK)) }
}

/// Run `f` on the function a builder builds; see [`with_module`].
pub(crate) unsafe fn with_builder<T>(
    fb: *mut FirBuilder,
    invalid: T,
    f: impl FnOnce(&mut FuncBuilder<'_>) -> Result<T, BuildError>,
) -> T {
    let Some(b) = (unsafe { fb.as_ref() }) else {
        return invalid;
    };
    unsafe {
        module_id(b.module, invalid, |m| match m.mb.current() {
            Some(mut fb) => Ok(f(&mut fb)?),
            None => fail(FIR_ERR_INVALID, "no function is being built"),
        })
    }
}

unsafe fn builder_status(
    fb: *mut FirBuilder,
    f: impl FnOnce(&mut FuncBuilder<'_>) -> Result<(), BuildError>,
) -> FirStatus {
    let Some(b) = (unsafe { fb.as_ref() }) else {
        return FIR_ERR_INVALID;
    };
    unsafe {
        module_status(b.module, |m| match m.mb.current() {
            Some(mut fb) => Ok(f(&mut fb)?),
            None => fail(FIR_ERR_INVALID, "no function is being built"),
        })
    }
}

// Conversions for the generated functions.

/// A list passed from C; empty when the length is 0, whatever the pointer.
pub(crate) unsafe fn list<'a, T>(p: *const T, n: usize) -> &'a [T] {
    if n == 0 || p.is_null() {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(p, n) }
    }
}

/// Operands passed from C: a `FirValue` is an operand's 32 bits.
pub(crate) unsafe fn values<'a>(p: *const FirValue, n: usize) -> &'a [Operand] {
    // `Operand` is `repr(transparent)` over `u32`, and every `u32` is an operand (one that names
    // nothing is rejected when used).
    unsafe { list(p.cast::<Operand>(), n) }
}

pub(crate) fn ty(t: FirType) -> Result<Ty, BuildError> {
    let n = t & !TY_TAG;
    Ok(match t & TY_TAG {
        0 => Ty::Int(n),
        TY_BYTE => Ty::Byte(n),
        TY_AGG => Ty::Agg(TyId::from_raw(n)),
        _ if t == FIR_TYPE_PTR => Ty::Ptr,
        _ if t == FIR_TYPE_SLICE => Ty::Slice,
        _ if t == FIR_TYPE_F32 => Ty::Float(FloatTy::F32),
        _ if t == FIR_TYPE_F64 => Ty::Float(FloatTy::F64),
        _ if t == FIR_TYPE_VA_LIST => Ty::VaList,
        _ => return Err(BuildError::new(format!("{t:#x} is not a type"))),
    })
}

fn ty_to_c(t: Ty) -> FirType {
    match t {
        Ty::Int(w) => w,
        Ty::Byte(w) => TY_BYTE | w,
        Ty::Agg(id) => TY_AGG | id.raw(),
        Ty::Ptr => FIR_TYPE_PTR,
        Ty::Slice => FIR_TYPE_SLICE,
        Ty::Float(FloatTy::F32) => FIR_TYPE_F32,
        Ty::Float(FloatTy::F64) => FIR_TYPE_F64,
        Ty::VaList => FIR_TYPE_VA_LIST,
    }
}

pub(crate) unsafe fn tys(p: *const FirType, n: usize) -> Result<Vec<Ty>, BuildError> {
    unsafe { list(p, n) }.iter().map(|&t| ty(t)).collect()
}

pub(crate) unsafe fn cstr<'a>(p: *const c_char) -> Result<&'a str, BuildError> {
    if p.is_null() {
        return Err(BuildError::new("a name is missing"));
    }
    unsafe { CStr::from_ptr(p) }
        .to_str()
        .map_err(|_| BuildError::new("a name is not UTF-8"))
}

pub(crate) fn target(t: FirTarget, args: &[Operand]) -> Target<'_> {
    Target::new(RegionId::from_raw(t.block), args)
}

pub(crate) unsafe fn switch_cases<'a>(p: *const FirCase, n: usize) -> Vec<SwitchCase<'a>> {
    unsafe { list(p, n) }
        .iter()
        .map(|c| SwitchCase {
            key: c.key.into(),
            target: target(c.target, unsafe { values(c.target.args, c.target.nargs) }),
        })
        .collect()
}

// Float constants from C values.

/// `float.const` of type `f32` with the bits of a C `float` (NaN payloads included).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_float_const_f32(fb: *mut FirBuilder, value: f32) -> FirValue {
    unsafe { fir_float_const(fb, FIR_TYPE_F32, u64::from(value.to_bits())) }
}

/// `float.const` of type `f64` with the bits of a C `double` (NaN payloads included).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_float_const_f64(fb: *mut FirBuilder, value: f64) -> FirValue {
    unsafe { fir_float_const(fb, FIR_TYPE_F64, value.to_bits()) }
}

// Modules.

/// The API version the library was built with: `FIR_API_VERSION`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_api_version() -> u32 {
    FIR_API_VERSION
}

/// A new, empty module. Free it with `fir_module_free`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_module_new() -> *mut FirModule {
    Box::into_raw(Box::new(FirModule {
        mb: ModuleBuilder::new(),
        inits: Vec::new(),
        error: CString::default(),
    }))
}

/// Parse FIR text into a new module (`*out`), to verify, print, run, or add to. On failure,
/// `*error` gets the message, which the caller frees with `fir_string_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_parse(
    text: *const c_char,
    out: *mut *mut FirModule,
    error: *mut *mut c_char,
) -> FirStatus {
    let r = catch_unwind(|| -> Result<ModuleBuilder, (FirStatus, String)> {
        let text = unsafe { cstr(text) }.map_err(|e| (FIR_ERR_INVALID, e.to_string()))?;
        let m = fir::parse_module(text).map_err(|e| (FIR_ERR_PARSE, e))?;
        ModuleBuilder::from_module(m).map_err(|e| (FIR_ERR_INVALID, e.to_string()))
    })
    .unwrap_or_else(|p| Err((FIR_ERR_INTERNAL, panic_message(&*p))));
    match r {
        Ok(mb) => {
            if let Some(out) = unsafe { out.as_mut() } {
                *out = Box::into_raw(Box::new(FirModule {
                    mb,
                    inits: Vec::new(),
                    error: CString::default(),
                }));
            }
            FIR_OK
        }
        Err((status, msg)) => {
            if let Some(error) = unsafe { error.as_mut() } {
                *error = c_string(msg).into_raw();
            }
            status
        }
    }
}

/// Free a module and everything in it. A builder of it can't be used afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_free(m: *mut FirModule) {
    if !m.is_null() {
        drop(unsafe { Box::from_raw(m) });
    }
}

/// The message of the module's last failed call (empty if none failed). It belongs to the
/// module, and lasts until its next failed call.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_error(m: *const FirModule) -> *const c_char {
    match unsafe { m.as_ref() } {
        Some(m) => m.error.as_ptr(),
        None => c"no module".as_ptr(),
    }
}

/// Free a string FIR returned.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_string_free(s: *mut c_char) {
    if !s.is_null() {
        drop(unsafe { CString::from_raw(s) });
    }
}

/// Set the default memory space's data layout: pointer and address sizes in bits, the pointer
/// alignment in bytes (0: the natural one), and the integer alignments by increasing width (none:
/// the default ones). Set it before building functions.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_set_space(
    m: *mut FirModule,
    ptr_bits: u32,
    addr_bits: u32,
    ptr_align: u32,
    ints: *const FirIntAlign,
    nints: usize,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let mut sp = SpaceCfg {
                ptr_bits,
                addr_bits,
                ptr_align: if ptr_align == 0 {
                    SpaceCfg::natural_align(ptr_bits)
                } else {
                    ptr_align
                },
                ..SpaceCfg::default()
            };
            if nints > 0 {
                sp.ints = list(ints, nints)
                    .iter()
                    .map(|e| (e.width, e.align))
                    .collect();
            }
            m.mb.set_space(sp);
            Ok(())
        })
    }
}

/// Set the size and alignment in bytes of the module's `va_list` (its memory space's `valist`;
/// 32 and 8 by default). Set it before building functions.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_set_va_list(
    m: *mut FirModule,
    size: u32,
    align: u32,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let sp = SpaceCfg {
                va_size: size,
                va_align: align,
                ..m.mb.module().space.clone()
            };
            m.mb.set_space(sp);
            Ok(())
        })
    }
}

/// Set the module's layer: HFIR (the default), MFIR, or LFIR for the target `target` (such as
/// `"aarch64"`; ignored for the other layers). Set it before building functions: each op is
/// checked against it as it is built.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_set_layer(
    m: *mut FirModule,
    layer: FirLayer,
    target: *const c_char,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let layer = match layer {
                FIR_LAYER_HFIR => fir::Layer::Hfir,
                FIR_LAYER_MFIR => fir::Layer::Mfir,
                FIR_LAYER_LFIR => {
                    let name = cstr(target)?;
                    match fir::Layer::target(name) {
                        Some(t) => fir::Layer::Lfir(t),
                        None => return fail(FIR_ERR_INVALID, format!("unknown target '{name}'")),
                    }
                }
                n => return fail(FIR_ERR_INVALID, format!("{n} is not a FirLayer")),
            };
            m.mb.set_layer(layer);
            Ok(())
        })
    }
}

/// Check the module (its finished functions) as `fir check` does. On failure the message is the
/// verifier's.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_verify(m: *mut FirModule) -> FirStatus {
    unsafe {
        module_status(m, |m| match fir::verify_module(m.mb.module()) {
            Ok(_) => Ok(()),
            Err(e) => fail(FIR_ERR_VERIFY, e),
        })
    }
}

/// The module (its finished functions) in canonical text, with locations or without. Free it with
/// `fir_string_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_print(m: *mut FirModule, show_locs: bool) -> *mut c_char {
    unsafe {
        module_id(m, std::ptr::null_mut(), |m| {
            Ok(c_string(m.mb.module().render(show_locs)).into_raw())
        })
    }
}

/// Verify the module, then run `@name` with arguments written as text (integers, `null`,
/// `poison`) for at most `fuel` steps. `*out` gets the outcome in one line, as `fir run` prints
/// it (`returned i32 3`, `ub div0 @4:3`, …); free it with `fir_string_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_run(
    m: *mut FirModule,
    name: *const c_char,
    args: *const *const c_char,
    nargs: usize,
    fuel: u64,
    out: *mut *mut c_char,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let name = cstr(name)?;
            let args = list(args, nargs)
                .iter()
                .map(|&a| cstr(a))
                .collect::<Result<Vec<_>, _>>()?;
            let module = m.mb.module();
            if let Err(e) = fir::verify_module(module) {
                return fail(FIR_ERR_VERIFY, e);
            }
            match fir::interp::run(module, name, &args, fuel) {
                Ok(line) => {
                    if let Some(out) = out.as_mut() {
                        *out = c_string(line).into_raw();
                    }
                    Ok(())
                }
                Err(e) => fail(FIR_ERR_RUN, e),
            }
        })
    }
}

/// A new module, `*out`, from a verified copy of `m` (its finished functions). `m` is unchanged.
unsafe fn derive(
    m: *mut FirModule,
    out: *mut *mut FirModule,
    f: impl FnOnce(&fir::Module) -> Result<fir::Module, Fail>,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let module = m.mb.module();
            if let Err(e) = fir::verify_module(module) {
                return fail(FIR_ERR_VERIFY, e);
            }
            let new = f(module)?;
            let mb = ModuleBuilder::from_module(new)?;
            if let Some(out) = out.as_mut() {
                *out = Box::into_raw(Box::new(FirModule {
                    mb,
                    inits: Vec::new(),
                    error: CString::default(),
                }));
            }
            Ok(())
        })
    }
}

/// Verify an HFIR module and lower it to MFIR, as `fir lower` does: `*out` gets a new MFIR
/// module (free it with `fir_module_free`), and `m` is unchanged. The building blocks become
/// core ops, and aggregate, union, and slice values their scalars, so the lowered functions take
/// and return those scalars. `FIR_ERR_VERIFY` if `m` doesn't verify, `FIR_ERR_COMPILE` if it
/// can't be lowered (such as a field offset the address size can't hold).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_lower(
    m: *mut FirModule,
    out: *mut *mut FirModule,
) -> FirStatus {
    unsafe {
        derive(m, out, |module| {
            if module.layer != fir::Layer::Hfir {
                return fail(FIR_ERR_INVALID, "only an HFIR module can be lowered");
            }
            fir::lower_checked(module).or_else(|e| fail(FIR_ERR_COMPILE, e))
        })
    }
}

/// Verify a module and run the default pass pipeline on a copy, as `fir opt -O` does: `*out`
/// gets the optimized module, verified (free it with `fir_module_free`), and `m` is unchanged.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_optimize(
    m: *mut FirModule,
    out: *mut *mut FirModule,
) -> FirStatus {
    unsafe {
        derive(m, out, |module| {
            let mut new = module.clone();
            fir::passes::Pipeline::default_opt()
                .run(&mut new, &mut fir::passes::Remarks::new(false))
                .or_else(|e| fail(FIR_ERR_COMPILE, e.to_string()))?;
            match fir::verify_module(&new) {
                Ok(_) => Ok(new),
                Err(e) => fail(
                    FIR_ERR_COMPILE,
                    format!("the optimized module doesn't verify: {e}"),
                ),
            }
        })
    }
}

/// Verify a module and compile it for `target` (`"aarch64"`, the only one so far) to GNU
/// assembly, as `fir compile --emit asm` does: HFIR is lowered to MFIR first, and with
/// `optimize` the default pass pipeline runs on the MFIR (`fir compile -O`). `*out` gets the
/// assembly text; free it with `fir_string_free`. `FIR_ERR_COMPILE` if the module uses what the
/// backend doesn't support yet (integers wider than 64 bits, floats, holes, other data layouts).
/// Exceptions use an error-return convention: an exception that escapes a compiled function is
/// pending in `struct { void *flag; void *value; } __fir_exn` (nonzero `flag`) when it returns;
/// a C caller checks `flag` after the call, and clears it to catch.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_compile(
    m: *mut FirModule,
    target: *const c_char,
    optimize: bool,
    os: FirOs,
    out: *mut *mut c_char,
) -> FirStatus {
    use fir::backend::aarch64 as a64;
    unsafe {
        module_status(m, |m| {
            let target = cstr(target)?;
            if target != "aarch64" {
                return fail(FIR_ERR_INVALID, format!("unknown target '{target}'"));
            }
            let os = match os {
                FIR_OS_LINUX => a64::Os::Linux,
                FIR_OS_DARWIN => a64::Os::Darwin,
                n => return fail(FIR_ERR_INVALID, format!("{n} is not a FirOs")),
            };
            let module = m.mb.module();
            if let Err(e) = fir::verify_module(module) {
                return fail(FIR_ERR_VERIFY, e);
            }
            let o = a64::Options {
                os,
                ..a64::Options::default()
            };
            let asm = fir::backend::prepare(module, optimize)
                .and_then(|l| a64::compile(&l, &o))
                .or_else(|e| fail(FIR_ERR_COMPILE, e))?;
            if let Some(out) = out.as_mut() {
                *out = c_string(asm).into_raw();
            }
            Ok(())
        })
    }
}

// Types.

/// `iN`, for `1 <= width < 2^30`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_type_int(width: u32) -> FirType {
    if width == 0 || width & TY_TAG != 0 {
        FIR_INVALID
    } else {
        width
    }
}

/// `bN`, for `1 <= width < 2^30`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_type_byte(width: u32) -> FirType {
    if width == 0 || width & TY_TAG != 0 {
        FIR_INVALID
    } else {
        TY_BYTE | width
    }
}

/// `struct<policy>{fields}`
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_struct(
    m: *mut FirModule,
    policy: FirPolicy,
    fields: *const FirType,
    nfields: usize,
) -> FirType {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let fields = tys(fields, nfields)?;
            Ok(ty_to_c(m.mb.struct_ty(Policy::from_c(policy)?, &fields)?))
        })
    }
}

/// `array<n x elem>`
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_array(m: *mut FirModule, n: u64, elem: FirType) -> FirType {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            Ok(ty_to_c(m.mb.array_ty(n, ty(elem)?)?))
        })
    }
}

/// `union<variants>` (HFIR): one of the variants, value types, and an `i32` tag naming it.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_union(
    m: *mut FirModule,
    variants: *const FirType,
    nvariants: usize,
) -> FirType {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let vs = tys(variants, nvariants)?;
            Ok(ty_to_c(m.mb.union_ty(&vs)?))
        })
    }
}

/// `func<(params) -> rets>`, the signature of `func.call.indirect`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_func(
    m: *mut FirModule,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
) -> FirType {
    unsafe { fir_type_func_va(m, params, nparams, rets, nrets, false) }
}

/// `func<(params, ...) -> rets>` if `variadic`, else `func<(params) -> rets>`: the signature of
/// an indirect call of a variadic function, which passes variadic arguments after `params`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_func_va(
    m: *mut FirModule,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
    variadic: bool,
) -> FirType {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            Ok(ty_to_c(m.mb.func_ty_va(&ps, &rs, variadic)?))
        })
    }
}

// Layout.

/// A type of the module that has a layout in memory: a scalar, a struct, or an array.
fn layout_ty(m: &FirModule, t: FirType) -> Result<Ty, Fail> {
    let t = ty(t)?;
    match t {
        Ty::Agg(id) if id.index() >= m.mb.types().len() => fail(
            FIR_ERR_INVALID,
            format!("type {} is not a type of this module", id.index()),
        ),
        Ty::Agg(id) => match m.mb.types().shape(id) {
            fir::Shape::Func(..) | fir::Shape::Union(_) => fail(
                FIR_ERR_INVALID,
                format!("{} has no layout in memory", m.mb.types().show(t)),
            ),
            _ => Ok(t),
        },
        _ => Ok(t),
    }
}

/// A type's size and alignment in bytes, in the module's memory space (its data layout), as
/// `ty.size` and `ty.align` give them: what a frontend checks its own layout against. Scalars,
/// structs, and arrays have a layout; function and union types don't.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_layout(
    m: *mut FirModule,
    t: FirType,
    size: *mut u64,
    align: *mut u32,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let t = layout_ty(m, t)?;
            let (s, a) = m.mb.types().dims(&m.mb.module().space, t);
            let Ok(s) = u64::try_from(s) else {
                return fail(
                    FIR_ERR_INVALID,
                    "the type is too large for the address space",
                );
            };
            if let Some(size) = size.as_mut() {
                *size = s;
            }
            if let Some(align) = align.as_mut() {
                *align = u32::try_from(a).unwrap_or(u32::MAX);
            }
            Ok(())
        })
    }
}

/// The offset in bytes of field `index` of the struct type `t`, as `ty.offset` gives it.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_field_offset(
    m: *mut FirModule,
    t: FirType,
    index: u32,
    offset: *mut u64,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let t = layout_ty(m, t)?;
            let types = m.mb.types();
            let Some(o) = types.field_offset(&m.mb.module().space, t, index) else {
                return fail(
                    FIR_ERR_INVALID,
                    format!("{} has no field {index}", types.show(t)),
                );
            };
            let Ok(o) = u64::try_from(o) else {
                return fail(
                    FIR_ERR_INVALID,
                    "the offset is too large for the address space",
                );
            };
            if let Some(offset) = offset.as_mut() {
                *offset = o;
            }
            Ok(())
        })
    }
}

// Declarations.

/// Declare a function `@name(params) -> rets`, to call it or take its address, and define it
/// with `fir_func_begin`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_declare(
    m: *mut FirModule,
    name: *const c_char,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            Ok(m.mb.declare_func(cstr(name)?, &ps, &rs)?.raw())
        })
    }
}

/// `fir_func_declare` of a function that takes variadic arguments after `params` if
/// `variadic` (`func @name(%a: T, ...)`): its body reads them with `fir_va_start` and
/// `fir_va_arg`, and a call (`fir_func_call`) passes them after the fixed arguments.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_declare_va(
    m: *mut FirModule,
    name: *const c_char,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
    variadic: bool,
) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            Ok(m.mb.declare_func_va(cstr(name)?, &ps, &rs, variadic)?.raw())
        })
    }
}

/// The function or external function named `name`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_find(m: *mut FirModule, name: *const c_char) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let name = cstr(name)?;
            match m.mb.func_ref(name) {
                Some(f) => Ok(f.raw()),
                None => fail(FIR_ERR_INVALID, format!("no function @{name}")),
            }
        })
    }
}

/// `extern func @name(params) -> rets effects[…] trust`: a function outside the module, with the
/// `FIR_EFFECT_*` it may have.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_extern_declare(
    m: *mut FirModule,
    name: *const c_char,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
    effects: *const FirEffect,
    neffects: usize,
    trust: FirTrust,
) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            let es = list(effects, neffects)
                .iter()
                .map(|&e| ExtEffect::from_c(e))
                .collect::<Result<Vec<_>, _>>()?;
            let f =
                m.mb.extern_func(cstr(name)?, &ps, &rs, &es, Trust::from_c(trust)?)?;
            Ok(f.raw())
        })
    }
}

/// `fir_extern_declare` of a function that takes variadic arguments after `params` if
/// `variadic` (`extern func @printf(ptr, ...) -> i32 …`).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_extern_declare_va(
    m: *mut FirModule,
    name: *const c_char,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
    variadic: bool,
    effects: *const FirEffect,
    neffects: usize,
    trust: FirTrust,
) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            let es = list(effects, neffects)
                .iter()
                .map(|&e| ExtEffect::from_c(e))
                .collect::<Result<Vec<_>, _>>()?;
            let trust = Trust::from_c(trust)?;
            let f =
                m.mb.extern_func_va(cstr(name)?, &ps, &rs, variadic, &es, trust)?;
            Ok(f.raw())
        })
    }
}

/// `global [const] @name: ty [align align] = init`. An initializer that takes the address of a
/// global declared later is set afterwards with `fir_global_set_init`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_global_declare(
    m: *mut FirModule,
    name: *const c_char,
    ty_: FirType,
    constant: bool,
    align: u32,
    init: FirInit,
) -> FirGlobal {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let init = m.init(init)?;
            let g = m.mb.global(cstr(name)?, ty(ty_)?, constant, align, init)?;
            Ok(g.raw())
        })
    }
}

/// Replace a global's initializer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_global_set_init(
    m: *mut FirModule,
    g: FirGlobal,
    init: FirInit,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let init = m.init(init)?;
            Ok(m.mb.set_global_init(GlobalRef::from_raw(g), init)?)
        })
    }
}

impl FirModule {
    fn init(&self, i: FirInit) -> Result<Init, BuildError> {
        match self.inits.get(i as usize) {
            Some(&init) => Ok(init),
            None => Err(BuildError::new(format!("initializer {i} does not exist"))),
        }
    }

    fn add_init(&mut self, init: Init) -> FirInit {
        self.inits.push(init);
        (self.inits.len() - 1) as FirInit
    }
}

/// `zero`: every byte zero.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_zero(m: *mut FirModule) -> FirInit {
    unsafe { module_id(m, FIR_INVALID, |m| Ok(m.add_init(Init::Zero))) }
}

